```csharp
using System;
using System.Net;
using System.IO;

class HttpServer
{
    static void Main(string[] args)
    {
        // Créer un nouvel objet HttpListener
        HttpListener listener = new HttpListener();

        // Configurer l'objet HttpListener pour écouter les requêtes à l'adresse http://localhost:8080
        listener.Prefixes.Add("http://localhost:8080/");

        // Démarre le listener pour écouter les requêtes
        listener.Start();

        Console.WriteLine("Serveur HTTP démarré. Appuyez sur une touche pour quitter.");

        // Boucle infinie pour attendre les requêtes
        while (true)
        {
            HttpListenerContext context = listener.GetContext();
            HttpListenerRequest request = context.Request;

            // Traitement de la requête
            if (request.Url.AbsolutePath == "/hello")
            {
                // Renvoyer une réponse avec le texte "Hello" et le code de statut 200 OK
                context.Response.ContentType = "text/plain";
                context.Response.Write("Hello");
                context.Response.StatusCode = 200;
                context.Response.Close();
            }
            else
            {
                // Renvoyer une réponse avec le code de statut 404 Not Found
                context.Response.StatusCode = 404;
                context.Response.Close();
            }
        }
    }
}
```
Ce code utilise l'objet `HttpListener` pour écouter les requêtes HTTP et renvoyer des réponses appropriées. Lorsqu'une requête est reçue, le code vérifie si la URL est "/hello" et, si c'est le cas, renvoie une réponse avec le texte "Hello". Sinon, il renvoie une réponse avec le code de statut 404 Not Found.

