class PasswordGenerator {
  constructor() {
    this.minLength = 12; // longitud mínima de la contraseña
    this.maxLength = 24; // longitud máxima de la contraseña
    this.chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%&*()_+-=?';
  }

  generatePassword() {
    let password = '';
    for (let i = 0; i < this.minLength; i++) {
      password += this.chars.charAt(Math.floor(Math.random() * this.chars.length));
    }
    return password;
  }

  generateStrongPassword() {
    let password = '';
    let types = ['uppercase', 'lowercase', 'number', 'specialChar'];
    let typeCount = 3; // número de tipos de caracteres que se incluían en la contraseña
    for (let i = 0; i < typeCount; i++) {
      let type = types[i];
      switch (type) {
        case 'uppercase':
          password += this.chars.toUpperCase().charAt(Math.floor(Math.random() * this.chars.length));
          break;
        case 'lowercase':
          password += this.chars.toLowerCase().charAt(Math.floor(Math.random() * this.chars.length));
          break;
        case 'number':
          password += '0123456789'.charAt(Math.floor(Math.random() * 10));
          break;
        case 'specialChar':
          password += '!@#$%&*()_+-=?'.charAt(Math.floor(Math.random() * 14));
          break;
      }
    }
    // Resto de la contraseña para alcanzar la longitudmínima
    for (let i = 0; i < this.minLength - typeCount; i++) {
      password += this.chars.charAt(Math.floor(Math.random() * this.chars.length));
    }
    return password;
  }
}
```
