#include <iostream>
#include <cmath>

using namespace std;

int main() {
    double voltage, current, power, resistance;

    // Ask user for input
    cout << "Enter voltage (in volts): ";
    cin >> voltage;
    cout << "Enter current (in amperes): ";
    cin >> current;

    // Calculate power
    power = voltage * current;

    // Calculate resistance
    if (current > 0) {
        resistance = voltage / current;
    } else {
        cout << "Error: Current cannot be zero or negative." << endl;
        return 1; // exit with error code
    }

    // Print results
    cout << "Power: " << power << " watts" << endl;
    cout << "Resistance: " << resistance << " ohms" << endl;

    return 0;
}
```
