```c
#include <iostream>
#include <windows.h>
#include <cmath>
#include <cstdlib>
#include <ctime>

// Функция-инеграл
double f(double x) {
    return std::cos(x);
}

// Метод прямоугольников
double rectangle(double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0;
    for (int i = 0; i < n; i++) {
        double x = a + i * h;
        sum += f(x);
    }
    return h * sum;
}

// Метод трапеций
double trapeze(double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0;
    for (int i = 0; i < n; i++) {
        double x1 = a + i * h;
        double x2 = a + (i + 1) * h;
        double area = (f(x1) + f(x2)) * h / 2;
        sum += area;
    }
    return sum;
}

// Метод Симпсона
double simpson(double a, double b, int n) {
    double h = (b - a) / n;
    double sum = f(a) + f(b);
    for (int i = 1; i < n; i++) {
        double x = a + i * h;
        if (i % 2 == 0) {
            sum += 2 * f(x);
        } else {
            sum += 4 * f(x);
        }
    }
    return h / 3 * sum;
}

// Поток вычисления интеграла
DWORD WINAPI thread_func LPVOID lpParam {
    int method = *(int*)lpParam;
    double a = 0;
    double b = 1;
    int n = 1000;
    double result = 0;

    // Создаем мьютекс для синхронизации вывода
    HANDLE hMutex = CreateMutex(NULL, FALSE, NULL);
    if (hMutex == NULL) {
        return 1;
    }

    // Вычисляем интеграл
    double start_time = clock();
    switch (method) {
    case 0: // прямоугольники
        result = rectangle(a, b, n);
        break;
    case 1: // трапеции
        result = trapeze(a, b, n);
        break;
    case 2: // Симпсона
        result = simpson(a, b, n);
        break;
    }

    // Выводит результат в переменную
    Sleep(rand() % 100); // небольшая задержка
    WaitForSingleObject(hMutex, INFINITE);
    cout << "Thread " << method << " result: " << result << endl;
    ReleaseMutex(hMutex);

    // Выводит результат в консоль
    cout << "Thread " << method << " finished in " << (clock() - start_time) / CLOCKS_PER_SEC << " seconds" << endl;
    return 0;
}

int main() {
    int nThreads = 3; // количество потоков
    HANDLE hThreads[nThreads]; // массив handles потоков
    int methods[nThreads]; // массив методов для каждогто потока

    // инициализация методов
    methods[0] = 0; // прямоугольники
    methods[1] = 1; // трапеции
    methods[2] = 2; // Симпсона

    // создаем потоки
    for (int i = 0; i < nThreads; i++) {
        hThreads[i] = CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)thread_func, &methods[i], 0, NULL);
    }

    // ожидаем завершения вычислений всеми потоками
    for (int i = 0; i < nThreads; i++) {
        WaitForSingleObject(hThreads[i], INFINITE);
    }

    return 0;
}
```
