```java
public class NetSniffer implements Runnable {
    private Socket socket;
    private String interfaceName;

    public NetSniffer(String interfaceName) {
        this.interfaceName = interfaceName;
    }

    @Override
    public void run() {
        try {
            // Cria um socket UDP para capturar pacotes
            socket = new DatagramSocket(0, InetAddress.getByName("0.0.0.0"));

            // Define a interface de rede a ser usada
            socket.setSoTimeout(1000); // em milisegundos
            socket.bind(new InetSocketAddress(interfaceName));

            while (true) {
                // Captura um pacote
                DatagramPacket packet = new DatagramPacket(new byte[1024], 1024);
                socket.receive(packet);

                // Imprime as informações do pacote
                System.out.println("Received packet:");
                System.out.println("  Source IP: " + packet.getAddress().getHostAddress());
                System.out.println("  Source Port: " + packet.getPort());
                System.out.println("  Destination IP: " + packet.getSocketAddress()..getAddress().getHostAddress());
                System.out.println("  Destination Port: " + packet.getSocketAddress().getPort());
                System.out.println("  Length: " + packet.getLength());
                System.out.println("  Data: " + new String(packet.getData(), 0, packet.getLength()));
            }
        } catch (SocketException e) {
            System.out.println("Erro ao criar socket: " + e.getMessage());
        } catch (IOException e) {
            System.out.println("Erro ao receber pacote: " + e.getMessage());
        } finally {
            if (socket != null) {
                socket.close();
            }
        }
    }
}
```
